import {createChatOrchestrator} from './orchestration/chatOrchestrator.js';
import {createMockProvider} from './providers/mock/index.js';
import {PromptBuilder} from './infrastructure/builders/promptBuilder.js';
import type {ChatSession} from './types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#10
it('reports a rejection with no prototype and preserves its identity', async () => {
  const reason: unknown = Object.create(null);
  const failures: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeUserInput: () => Promise.reject(reason),
        onError: async (_session, error) => void failures.push(error),
      },
    }
  );

  const rejection: unknown = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({
    count: failures.length,
    isError: failures[0] instanceof Error,
    hasMessage: Boolean(failures[0]?.message),
    sameCause: failures[0]?.cause === reason,
    sameRejection: rejection === reason,
  }).toEqual({count: 1, isError: true, hasMessage: true, sameCause: true, sameRejection: true});
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/chatOrchestrator.unprintable.test.ts"

